from pathlib import Path
import re
path = Path('/home/ubuntu/pathfinder-ai/client/src/pages/Home.tsx')
text = path.read_text()
plan = '''function Plan({ setView }: { setView: (s: string) => void }) { const [steps, setSteps] = useState([{ title: "Complete your PathFinder profile", detail: "Add your education, interests and location", done: true, custom: false }, { title: "Save one opportunity that fits", detail: "Start with the Digital Skills Internship", done: true, custom: false }, { title: "Check the entry requirements", detail: "Open the official page and note any gaps", done: false, custom: false }, { title: "Prepare your first application draft", detail: "Turn your context into a clear introduction", done: false, custom: false }]); const [customStep, setCustomStep] = useState(""); const completed = steps.filter(s => s.done).length; return <div><Pill color="green"><Target size={13} className="mr-1" /> My Pathways</Pill><div className="mt-4 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><h1 className="font-display text-4xl tracking-[-.04em]">Small moves,<br /><span className="text-[#0d9488]">real momentum.</span></h1><p className="mt-3 text-[#6c8490]">Your pathway checklist keeps the next step visible without making it feel heavy.</p></div><div className="rounded-2xl bg-white px-5 py-3 card-border"><span className="text-2xl font-bold text-[#0d9488]">{Math.round((completed / steps.length) * 100)}%</span><span className="ml-2 text-xs font-bold uppercase tracking-wider text-[#8aa0a8]">complete</span></div></div><div className="mt-10 grid gap-5 lg:grid-cols-[1fr_.7fr]"><div className="rounded-[24px] bg-white p-6 card-border"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">Your next steps</h2><Pill color="teal">{steps.length} milestones</Pill></div><div className="mt-5 h-2 overflow-hidden rounded-full bg-[#e6efef]"><div className="h-full rounded-full bg-[#22c55e] transition-all" style={{ width: `${(completed / steps.length) * 100}%` }} /></div><div className="mt-7 space-y-1">{steps.map((s, i) => <label key={`${s.title}-${i}`} className="flex cursor-pointer gap-4 rounded-2xl p-3 transition hover:bg-[#f7fafc]"><input type="checkbox" checked={s.done} onChange={() => setSteps(list => list.map((x, idx) => idx === i ? { ...x, done: !x.done } : x))} className="sr-only" /><div className={`mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${s.done ? "bg-[#dff7e8] text-[#258044]" : "border-2 border-[#cfe1e3] text-[#8aa0a8]"}`}>{s.done ? <Check size={15} /> : <span className="text-xs font-bold">{i + 1}</span>}</div><div><h3 className={`text-sm font-bold ${s.done ? "text-[#52717d] line-through decoration-[#b1c2c5]" : "text-[#183b56]"}`}>{s.title}</h3><p className="mt-1 text-xs text-[#8aa0a8]">{s.custom ? "Your custom step" : s.detail}</p></div></label>)}</div><div className="mt-5 flex gap-2"><input value={customStep} onChange={e => setCustomStep(e.target.value)} placeholder="Add your own step" className="h-11 flex-1 rounded-xl border border-[#dce9ea] px-3 text-sm outline-none focus:border-[#0d9488]" /><Button onClick={() => { if (customStep.trim()) { setSteps(list => [...list, { title: customStep.trim(), detail: "Added by you", done: false, custom: true }]); setCustomStep(""); } }}>Add</Button></div></div><div className="rounded-[24px] bg-[#183b56] p-6 text-white"><Pill color="teal">Your match explained</Pill><h2 className="font-display mt-5 text-3xl">87% match</h2><p className="mt-4 text-sm leading-6 text-white/65">This direction scored well because it connects with your interest in computers and your preference for practical, growing work.</p><div className="mt-7 space-y-3 text-sm"><div className="flex items-center justify-between"><span className="text-white/55">Interest overlap</span><strong className="text-[#8de3d6]">High</strong></div><div className="flex items-center justify-between"><span className="text-white/55">Pathway access</span><strong className="text-[#8de3d6]">Good</strong></div><div className="flex items-center justify-between"><span className="text-white/55">Location fit</span><strong className="text-[#8de3d6]">Flexible</strong></div></div><button onClick={() => setView("opportunities")} className="mt-8 flex items-center gap-2 text-sm font-bold text-[#8de3d6]">See matching opportunities <ArrowRight size={16} /></button></div></div></div> }'''
apps = '''function Applications({ applications, setApplications, onAdd }: { applications: { title: string; org: string; type: string; deadline: string; status: string }[]; setApplications: React.Dispatch<React.SetStateAction<{ title: string; org: string; type: string; deadline: string; status: string }[]>>; onAdd: () => void }) { const [draftOpen, setDraftOpen] = useState(false); const [draft, setDraft] = useState("Hello, I’m a motivated learner exploring opportunities to grow my skills and contribute meaningfully.\\n\\nI’m interested in this opportunity because it connects with my strengths and the direction I’m building towards. I’d welcome the chance to share more about what I can bring.\\n\\nKind regards,\\n[Your name]"); const [calendar, setCalendar] = useState(false); const statuses = ["Not started", "Applied", "Interview", "Waiting", "Accepted", "Not this time"]; const copyDraft = async () => navigator.clipboard?.writeText(draft); const emailDraft = () => { window.location.href = `mailto:?subject=${encodeURIComponent("Application draft")}&body=${encodeURIComponent(draft)}`; }; return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="coral"><BriefcaseBusiness size={13} className="mr-1" /> Follow-through</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">My applications</h1><p className="mt-3 text-[#6c8490]">Keep the real-world steps connected to your PathFinder plan.</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => setCalendar(!calendar)}>{calendar ? "List view" : "Calendar view"}</Button><Button onClick={onAdd}><PenLine size={16} /> Add application</Button></div></div><div className="mt-8 grid gap-4 sm:grid-cols-3"><Stat label="In progress" value="2" /><Stat label="Upcoming deadlines" value="2" /><Stat label="Positive outcomes" value="—" /></div>{calendar && <div className="mt-8 rounded-[24px] bg-white p-6 card-border"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">September 2026</h2><Pill color="coral">Deadlines marked</Pill></div><div className="mt-5 grid grid-cols-7 gap-2 text-center text-xs"><span className="p-2 font-bold text-[#8aa0a8]">M</span><span className="p-2 font-bold text-[#8aa0a8]">T</span><span className="p-2 font-bold text-[#8aa0a8]">W</span><span className="p-2 font-bold text-[#8aa0a8]">T</span><span className="p-2 font-bold text-[#8aa0a8]">F</span><span className="p-2 font-bold text-[#8aa0a8]">S</span><span className="p-2 font-bold text-[#8aa0a8]">S</span>{Array.from({ length: 30 }, (_, i) => <div key={i} className={`min-h-12 rounded-xl p-2 ${i === 20 || i === 29 ? "bg-[#fff0ea] font-bold text-[#d95d3f]" : "bg-[#f7fafc] text-[#52717d]"}`}>{i + 1}{(i === 20 || i === 29) && <span className="mx-auto mt-1 block h-1.5 w-1.5 rounded-full bg-[#ff7a59]" />}</div>)}</div></div>}<div className="mt-8 overflow-hidden rounded-[24px] bg-white card-border"><div className="hidden grid-cols-[1.3fr_.6fr_.6fr_.8fr] gap-4 border-b border-[#edf3f3] px-6 py-4 text-[11px] font-bold uppercase tracking-[.14em] text-[#8aa0a8] sm:grid"><span>Opportunity</span><span>Type</span><span>Deadline</span><span>Status</span></div>{applications.map((a, i) => <div key={i} className="grid gap-3 border-b border-[#edf3f3] px-5 py-5 last:border-0 sm:grid-cols-[1.3fr_.6fr_.6fr_.8fr] sm:items-center sm:gap-4 sm:px-6"><div><h3 className="text-sm font-bold">{a.title}</h3><p className="mt-1 text-xs text-[#8aa0a8]">{a.org}</p></div><div><span className="text-xs font-bold text-[#52717d]">{a.type}</span></div><div><span className="text-xs font-semibold text-[#52717d]">{a.deadline}</span></div><select value={a.status} onChange={e => setApplications(list => list.map((x, idx) => idx === i ? { ...x, status: e.target.value } : x))} className={`w-fit rounded-full border-0 px-3 py-1.5 text-xs font-bold outline-none ${a.status === "Accepted" ? "bg-[#dff7e8] text-[#258044]" : a.status === "Not started" ? "bg-[#fff0ea] text-[#d95d3f]" : "bg-[#e7efff] text-[#2563eb]"}`}>{statuses.map(s => <option key={s}>{s}</option>)}</select></div>)}</div><div className="mt-7 rounded-[22px] bg-[#e8f6f3] p-5 text-sm text-[#52717d]"><strong className="text-[#183b56]">Keep your application notes in one place.</strong> Update a status when you hear back, and PathFinder can help you prepare the next response.<button onClick={() => setDraftOpen(!draftOpen)} className="mt-4 flex items-center gap-2 font-bold text-[#0f766e]">{draftOpen ? "Hide application draft" : "Generate application draft"} <ArrowRight size={15} /></button>{draftOpen && <div className="mt-4 rounded-2xl bg-white p-4"><p className="font-bold text-[#183b56]">Starting draft — personalise before sending</p><textarea value={draft} onChange={e => setDraft(e.target.value)} className="mt-3 min-h-[220px] w-full rounded-xl border border-[#dce9ea] p-3 text-sm leading-6 text-[#52717d] outline-none focus:border-[#0d9488]" /><div className="mt-3 flex flex-wrap gap-2"><Button variant="outline" onClick={copyDraft}>Copy to clipboard</Button><Button variant="outline" onClick={() => window.print()}>Export as PDF</Button><Button variant="outline" onClick={emailDraft}>Send via email</Button></div><p className="mt-3 text-xs text-[#8aa0a8]">This is a starting draft, not a finished document. Personalise it and verify the official requirements before sending.</p></div>}</div></div> }'''
text = re.sub(r'function Plan\(.*?\nfunction Applications', plan + '\nfunction Applications', text, count=1, flags=re.S)
text = re.sub(r'function Applications\(.*?\nfunction Stat', apps + '\nfunction Stat', text, count=1, flags=re.S)
path.write_text(text)
